-- Datos ficticios solicitados por el responsable para poblar la experiencia de reseñas. source=demo los mantiene separados de opiniones verificadas.
ALTER TABLE reviews_product_reviews ADD COLUMN source TEXT NOT NULL DEFAULT 'verified' CHECK (source IN ('verified', 'demo'));

INSERT OR IGNORE INTO reviews_product_reviews (id, product_id, customer_id, rating, comment, status, source, created_at, updated_at) VALUES
('demo-review-shirt-1', '35326c88-2865-4d72-b2a9-3f4277e947fa', 'demo:shirt-1', 5, 'La tela es cómoda y el ajuste quedó muy bien. Me gustó para usarla todos los días.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-shirt-2', '35326c88-2865-4d72-b2a9-3f4277e947fa', 'demo:shirt-2', 4, 'El diseño combina fácil con diferentes prendas y el material se siente agradable.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-hoodie-1', '5e789d78-5ad7-4ca0-a97d-09e294d8076a', 'demo:hoodie-1', 5, 'Es suave y abriga bastante. El corte queda cómodo para usarlo varias horas.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-hoodie-2', '5e789d78-5ad7-4ca0-a97d-09e294d8076a', 'demo:hoodie-2', 4, 'El acabado está bien cuidado y el calce es cómodo. Lo volvería a elegir.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-cap-1', 'b8a3dd9e-e751-4f3d-9ba5-2637be4e826f', 'demo:cap-1', 5, 'Es ligera y se ajusta fácilmente. El estilo es sencillo, justo lo que buscaba.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-cap-2', 'b8a3dd9e-e751-4f3d-9ba5-2637be4e826f', 'demo:cap-2', 4, 'Queda bien y el material se siente resistente. Buena opción para completar el atuendo.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-pants-1', '4d9a298f-60ce-4e84-94b0-04e1e0e9282b', 'demo:pants-1', 5, 'Tiene buen espacio y los bolsillos son prácticos para llevar lo necesario.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-pants-2', '4d9a298f-60ce-4e84-94b0-04e1e0e9282b', 'demo:pants-2', 4, 'La tela parece resistente y el diseño permite moverse con comodidad.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-jacket-1', '8ab0ad33-4f95-4856-9207-1cb9560f9d15', 'demo:jacket-1', 5, 'Es liviana y práctica. Me sirve cuando cambia el clima durante el día.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-jacket-2', '8ab0ad33-4f95-4856-9207-1cb9560f9d15', 'demo:jacket-2', 4, 'El corte es cómodo y protege bien del viento. El diseño también es fácil de combinar.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-bag-1', 'd7257021-0e40-4f9d-9afb-eec1513e2620', 'demo:bag-1', 5, 'Tiene buen espacio para organizar las cosas y los compartimentos son útiles.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-bag-2', 'd7257021-0e40-4f9d-9afb-eec1513e2620', 'demo:bag-2', 4, 'La mochila es cómoda y se siente firme. Me gustó cómo quedan distribuidos los bolsillos.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-socks-1', '7d718f91-b626-4adc-a6e4-504a7f18bca7', 'demo:socks-1', 5, 'Son cómodas y suaves. El paquete resulta práctico para tener varias disponibles.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-socks-2', '7d718f91-b626-4adc-a6e4-504a7f18bca7', 'demo:socks-2', 4, 'El tejido se siente agradable y el largo funciona bien para usar con distintos zapatos.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-glasses-1', 'c34267a6-4f38-4c5b-8fdc-e48fb58ee0f4', 'demo:glasses-1', 5, 'El diseño aviador es liviano y cómodo. Los lentes se sienten bien puestos.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z'),
('demo-review-glasses-2', 'c34267a6-4f38-4c5b-8fdc-e48fb58ee0f4', 'demo:glasses-2', 4, 'La montura se siente ligera y el estilo es sobrio. Me gustó cómo se ve.', 'approved', 'demo', '2026-10-14T12:00:00.000Z', '2026-10-14T12:00:00.000Z');
